.radio {
  /* 24px floor — see Checkbox.css; radios stack the same way. */
  min-block-size: var(--space-6);
  --dot-size: 1.25rem;   /* md default; sm/lg below */
  /* Containing block for the hidden input — see Checkbox.css for what escapes
   * without it. */
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  cursor: pointer;
  font-size: var(--font-base);
  color: var(--foreground);
  line-height: var(--leading-snug);
}
.radio[data-size="sm"] { --dot-size: 1rem; font-size: var(--font-sm); }
.radio[data-size="lg"] { --dot-size: 1.5rem; font-size: var(--font-md); }
.radio[data-disabled] { opacity: var(--disabled-opacity); cursor: not-allowed; }
/* The same three answers every other control gives. The selection family gave
 * none of them: a checkbox did not acknowledge the pointer, did not answer the
 * press, and had no way to be marked wrong — so a required consent box could be
 * rejected by a form with nothing on screen saying which box was the problem. */
.radio:hover:not([data-disabled]) .radio-circle { border-color: var(--ring); }
.radio:active:not([data-disabled]) .radio-circle { border-color: var(--primary-active); }
.radio[data-invalid] .radio-circle { border-color: var(--destructive); }
.radio[data-invalid] .radio-input:focus-visible + .radio-circle { outline-color: var(--destructive); }


.radio-input { position: absolute; width: 1px; height: 1px; opacity: 0; margin: 0; }

.radio-circle {
  position: relative;
  flex-shrink: 0;
  width: var(--dot-size);
  height: var(--dot-size);
  border: 1.5px solid var(--border-strong, var(--border));
  border-radius: var(--radius-full);
  background: var(--background);
  transition: border-color var(--duration-fast);
}
.radio-input:checked + .radio-circle { border-color: var(--primary-accent); }
.radio-input:checked + .radio-circle::after {
  content: "";
  position: absolute;
  inset: 0;
  margin: auto;
  width: 50%;
  height: 50%;
  border-radius: var(--radius-full);
  background: var(--primary);
}
.radio-input:focus-visible + .radio-circle {
  outline: var(--focus-ring);
  outline-offset: var(--ring-offset);
}

.radio-group { display: flex; flex-direction: column; gap: var(--space-2); }

import './Radio.css'
import type { InputHTMLAttributes } from 'react'
import { cn } from '../lib/cn'

type Props = Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'size'> & {
  /** Visible label beside the dot. */
  label?: string
  /** Dot size: sm / md (default) / lg. */
  size?: 'sm' | 'md' | 'lg'
  /** The form rejected this set. Draws the red circle and the red focus ring —
   *  the VISUAL half only. The announcement belongs to `<RadioGroup invalid>`,
   *  because a single radio cannot carry `aria-invalid`: ARIA does not support
   *  it on `role="radio"`, and "nothing is chosen" is a fact about the set, not
   *  about any one option in it. */
  invalid?: boolean
}

/* Single custom radio, one option in a set where exactly one is chosen. Native <input type="radio"> (so a shared `name` gives
 * arrow-key navigation + form semantics for free), visually themed. 
   *
   * Copy: options are parallel: same part of speech, same length, same grain.
   * "Weekly" beside "Every Monday at 9" reads as two different questions.
   */
export function Radio({ label, size, invalid, className, disabled, ...rest }: Props) {
  return (
    <label
      className={cn('radio', className)}
      data-size={size}
      data-disabled={disabled || undefined}
      data-invalid={invalid || undefined}
    >
      <input type="radio" className="radio-input" disabled={disabled} {...rest} />
      <span className="radio-circle" aria-hidden="true" />
      {label && <span className="radio-label">{label}</span>}
    </label>
  )
}

import './Radio.css'
import { Radio } from './Radio'

type Option<T extends string> = { value: T; label: string; disabled?: boolean }

type Props<T extends string> = {
  /** Shared input name (groups the radios for keyboard nav + single selection). */
  name: string
  value: T
  onChange: (value: T) => void
  options: Option<T>[]
  /** Accessible group label (for screen readers). */
  label?: string
  size?: 'sm' | 'md' | 'lg'
  /** The form rejected the set: nothing chosen where a choice was required.
   *  Marks every option red AND announces it here, on the group — which is the
   *  only element allowed to carry it, and the only one the fact is about. */
  invalid?: boolean
}

/* A set of radios sharing one name. Native radios handle arrow-key navigation. */
export function RadioGroup<T extends string>({ name, value, onChange, options, label, size, invalid }: Props<T>) {
  return (
    <div className="radio-group" role="radiogroup" aria-label={label} aria-invalid={invalid || undefined}>
      {options.map((o) => (
        <Radio
          key={o.value}
          name={name}
          value={o.value}
          size={size}
          checked={value === o.value}
          disabled={o.disabled}
          onChange={() => onChange(o.value)}
          invalid={invalid}
          label={o.label}
        />
      ))}
    </div>
  )
}
